    times.push({ text: pt(((h % 12) || 12) + ':' + String(mm).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM')), value: String(h).padStart(2, '0') + ':' + String(mm).padStart(2, '0') }); }
